const $=s=>document.querySelector(s);
const words={es:{title:'IA para desastres',review:'Resultados de apoyo sujetos a revisión humana. No son órdenes de atención ni evaluaciones estructurales certificadas.',sos:'Mensajes SOS',message:'Mensaje original',language:'Idioma del mensaje',translation:'Traducción local español-inglés. Si se configura DeepL como alternativa, el texto se envía a ese servicio. El original se conserva en el servidor.',analyze:'Analizar',queue:'Mensajes recibidos · revisión humana',damage:'Daños satelitales',images:'Carga un par de imágenes alineadas de 1024 × 1024. Indica sus límites WGS84: oeste, sur, este, norte.',pre:'Antes del desastre',post:'Después del desastre',download:'Descargar GeoJSON'},en:{title:'Disaster AI',review:'Decision support requiring human review. These results are not response orders or certified structural assessments.',sos:'SOS messages',message:'Original message',language:'Message language',translation:'Local Spanish-English translation. If DeepL is configured as a fallback, text is sent to that service. The original is stored on the server.',analyze:'Analyze',queue:'Received messages · human review',damage:'Satellite damage assessment',images:'Upload aligned 1024 × 1024 images. Enter WGS84 bounds: west, south, east, north.',pre:'Before disaster',post:'After disaster',download:'Download GeoJSON'}};
let engineState='checking',engineDetails=null;
const engineMessages={es:{checking:'Comprobando el servidor de IA…',unavailable:'Interfaz publicada. Para analizar mensajes o imágenes, abre esta aplicación desde el servidor de IA con los modelos instalados. GitHub Pages no ejecuta inferencias.',available:'Servidor de IA conectado. La disponibilidad de cada modelo se indica a continuación.'},en:{checking:'Checking the AI server…',unavailable:'Published interface. To analyze messages or images, open this application from the AI server with the models installed. GitHub Pages does not run inference.',available:'AI server connected. Model availability is shown below.'}};
function renderEngineStatus(){const lang=$('#locale').value;$('#engine-status').textContent=engineMessages[lang][engineState]+(engineDetails?' '+JSON.stringify(engineDetails):'');}
$('#locale').onchange=()=>{const lang=$('#locale').value;document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=words[lang][e.dataset.i18n]);renderEngineStatus();};
async function api(path,options){const r=await fetch('./api/v1/'+path,options);if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('API no disponible / API unavailable');const d=await r.json();if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));return d;}
async function refresh(){try{const rows=await api('messages');$('#message-list').replaceChildren(...rows.map(r=>{const tr=document.createElement('tr');for(const value of [r.created,r.original_text,r.priority]){const td=document.createElement('td');td.textContent=value;tr.append(td);}return tr;}));}catch{}}
document.querySelectorAll('form button').forEach(button=>button.disabled=true);
renderEngineStatus();
$('#sos-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=await api('analyze-text',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:$('#sos-text').value,language:$('#sos-language').value})});$('#sos-result').textContent=JSON.stringify(d,null,2);await refresh();}catch(err){$('#sos-result').textContent=err.message;}finally{b.disabled=false;}};
let map,layer,download;
if(window.L){map=L.map('damage-map').setView([3.45,-76.53],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors'}).addTo(map);}
$('#damage-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;$('#damage-result').textContent='Procesando / Processing…';try{const d=await api('analyze-damage',{method:'POST',body:new FormData(e.target)});$('#damage-result').textContent=d.features.length+' regiones / regions · 1 sin daño / no damage · 2 menor / minor · 3 mayor / major · 4 destruido / destroyed';if(map){if(layer)map.removeLayer(layer);layer=L.geoJSON(d,{style:f=>({color:['','#2a9d65','#e6b422','#ef7d32','#cf303f'][f.properties.damage_class],weight:2,fillOpacity:.5}),onEachFeature:(f,l)=>l.bindTooltip(f.properties.damage)}).addTo(map);if(d.features.length)map.fitBounds(layer.getBounds());}if(download)URL.revokeObjectURL(download);download=URL.createObjectURL(new Blob([JSON.stringify(d)],{type:'application/geo+json'}));$('#download').href=download;$('#download').hidden=false;}catch(err){$('#damage-result').textContent=err.message;}finally{b.disabled=false;}};
let retry,activeSocket,leaving=false;
function connect(){if(leaving)return;const ws=activeSocket=new WebSocket(new URL('./api/v1/messages/ws',location.href).href.replace(/^http/,'ws'));ws.onmessage=refresh;ws.onclose=()=>{if(!leaving)retry=setTimeout(connect,5000);};ws.onerror=()=>ws.close();}
api('status').then(d=>{engineState='available';engineDetails=d;renderEngineStatus();document.querySelectorAll('form button').forEach(button=>button.disabled=false);refresh();connect();}).catch(()=>{engineState='unavailable';renderEngineStatus();});
window.addEventListener('pagehide',()=>{leaving=true;clearTimeout(retry);activeSocket?.close();});
